mapper.select:
SELECT MSTA.CRSRD_ID ,MSTA.CAMERA_ID ,SUM(MSTA.STRGHT_TRFVLM) AS STRGHT_TRFVLM ,SUM(MSTA.TRNGHT_TRFVLM) AS TRNGHT_TRFVLM ,SUM(MSTA.TRNLFT_TRFVLM) AS TRNLFT_TRFVLM ,SUM(MSTA.STRGHT_TRFVLM) + SUM(MSTA.TRNGHT_TRFVLM) + SUM(MSTA.TRNLFT_TRFVLM) AS TRFVLM_TOTAL ,SUM(MSTA.WTLN_LEN) AS WTLN_LEN ,MSTA.ETL_DT ,ASCI.NODE_ID ,ASCI.CRSRD_NM ,ASCI.LON_CRDN ,ASCI.LAT_CRDN ,ASCI.MNG_INST_CD FROM MRT_SMCRSRD_TRFVLM_ANAL MSTA INNER JOIN ADSI_SMCRSRD_CRSRD_INFO ASCI ON MSTA.CRSRD_ID = ASCI.CRSRD_ID INNER JOIN C_GM_STD_NODE_ADSTDG_MPPG CGSNAM ON ASCI.NODE_ID = CGSNAM.NODE_ID WHERE 1=1
AND TO_CHAR(MSTA.PRDCTN_DT, 'YYYY') = #{searchYear}
AND TO_CHAR(MSTA.PRDCTN_DT, 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN '06' AND '10'
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN '17' AND '20'
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN #{startTime} AND #{endTime}
AND SUBSTRING(CGSNAM.ADSTDG_CD,0,5) = SUBSTRING(#{searchLocation},0,5)
GROUP by MSTA.CRSRD_ID, MSTA.CAMERA_ID, MSTA.ETL_DT, ASCI.NODE_ID, ASCI.CRSRD_NM, ASCI.LON_CRDN, ASCI.LAT_CRDN, ASCI.MNG_INST_CD

select MSTA.CRSRD_ID ,MSTA.CAMERA_ID ,string_agg(yyyymmdd||'='||TRFVLM_TOTAL, ',') as time_group_txt ,MSTA.NODE_ID ,MSTA.CRSRD_NM ,MSTA.LON_CRDN ,MSTA.LAT_CRDN ,MSTA.MNG_INST_CD FROM( SELECT TO_CHAR(MSTA.PRDCTN_DT, 'YYYY-MM-DD') as yyyymmdd ,MSTA.CRSRD_ID ,MSTA.CAMERA_ID ,SUM(MSTA.STRGHT_TRFVLM) AS STRGHT_TRFVLM ,SUM(MSTA.TRNGHT_TRFVLM) AS TRNGHT_TRFVLM ,SUM(MSTA.TRNLFT_TRFVLM) AS TRNLFT_TRFVLM ,SUM(MSTA.STRGHT_TRFVLM) + SUM(MSTA.TRNGHT_TRFVLM) + SUM(MSTA.TRNLFT_TRFVLM) AS TRFVLM_TOTAL ,SUM(MSTA.WTLN_LEN) AS WTLN_LEN ,MSTA.ETL_DT ,ASCI.NODE_ID ,ASCI.CRSRD_NM ,ASCI.LON_CRDN ,ASCI.LAT_CRDN ,ASCI.MNG_INST_CD FROM MRT_SMCRSRD_TRFVLM_ANAL MSTA INNER JOIN ADSI_SMCRSRD_CRSRD_INFO ASCI ON MSTA.CRSRD_ID = ASCI.CRSRD_ID INNER JOIN C_GM_STD_NODE_ADSTDG_MPPG CGSNAM ON ASCI.NODE_ID = CGSNAM.NODE_ID WHERE 1=1
AND TO_CHAR(MSTA.PRDCTN_DT, 'YYYY') = #{searchYear}
AND TO_CHAR(MSTA.PRDCTN_DT, 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN '06' AND '10'
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN '17' AND '20'
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN #{startTime} AND #{endTime}
AND SUBSTRING(CGSNAM.ADSTDG_CD,0,5) = SUBSTRING(#{searchLocation},0,5)
GROUP by MSTA.CRSRD_ID, MSTA.CAMERA_ID, MSTA.ETL_DT, ASCI.NODE_ID, ASCI.CRSRD_NM, ASCI.LON_CRDN, ASCI.LAT_CRDN, ASCI.MNG_INST_CD, TO_CHAR(MSTA.PRDCTN_DT, 'YYYY-MM-DD') ) MSTA group by MSTA.CRSRD_ID, MSTA.CAMERA_ID, MSTA.NODE_ID, MSTA.CRSRD_NM, MSTA.LON_CRDN, MSTA.LAT_CRDN, MSTA.MNG_INST_CD

select MSTA.TRFVLM_TOTAL ,MSTA.yyyymmdd ,MSTA.adstdg_cd FROM( select TO_CHAR(MSTA.PRDCTN_DT, 'YYYY-MM-DD') as yyyymmdd ,SUM(MSTA.STRGHT_TRFVLM) AS STRGHT_TRFVLM ,SUM(MSTA.TRNGHT_TRFVLM) AS TRNGHT_TRFVLM ,SUM(MSTA.TRNLFT_TRFVLM) AS TRNLFT_TRFVLM ,SUM(MSTA.STRGHT_TRFVLM) + SUM(MSTA.TRNGHT_TRFVLM) + SUM(MSTA.TRNLFT_TRFVLM) AS TRFVLM_TOTAL ,SUM(MSTA.WTLN_LEN) AS WTLN_LEN ,substring(CGSNAM.adstdg_cd,0, 6) as adstdg_cd FROM MRT_SMCRSRD_TRFVLM_ANAL MSTA INNER JOIN ADSI_SMCRSRD_CRSRD_INFO ASCI ON MSTA.CRSRD_ID = ASCI.CRSRD_ID INNER JOIN C_GM_STD_NODE_ADSTDG_MPPG CGSNAM ON ASCI.NODE_ID = CGSNAM.NODE_ID WHERE 1=1
AND TO_CHAR(MSTA.PRDCTN_DT, 'YYYY') = #{searchYear}
AND TO_CHAR(MSTA.PRDCTN_DT, 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN '06' AND '10'
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN '17' AND '20'
AND TO_CHAR(MSTA.PRDCTN_DT, 'HH24') BETWEEN #{startTime} AND #{endTime}
AND SUBSTRING(CGSNAM.ADSTDG_CD,0,5) = SUBSTRING(#{searchLocation},0,5)
GROUP by substring(CGSNAM.adstdg_cd,0, 6) ,TO_CHAR(MSTA.PRDCTN_DT, 'YYYY-MM-DD') ) MSTA group by MSTA.TRFVLM_TOTAL,MSTA.adstdg_cd,MSTA.yyyymmdd
